      hu: ["Területe 3710 négyzetkilométer", "Hivatalosan 1996-ban alapították", "Több mint 500 madárfaj él itt", "A Guyanai-pajzs része", "Híres a 154 méter hosszú lombkorona-sétányról", "A makusi őslakosok aktív közreműködésével kezelik"],
      ro: ["Suprafață de 3.710 km pătrați", "Înființată prin lege în anul 1996", "Adăpostește peste 500 de specii de păsări", "Localizată geografic în centrul Guyanei", "Include muntele Iwokrama ca punct dominant", "Parteneriat cu 20 de sate indigene Makushi"],
      en: ["Covers 3,710 square kilometers of rainforest", "Established as a reserve in 1996", "Home to over 500 bird species", "Located on the ancient Guiana Shield", "Features a 154-meter long canopy walkway", "Managed in partnership with Makushi communities"],
