      ro: ["Suprafață de aproximativ 160 de acri", "Situată pe râul Essequibo lângă Bartica", "Peste 180 de specii de păsări inventariate", "Numită după leneșul cu trei degete", "Accesibilă doar pe cale fluvială", "Destinație dedicată exclusiv ecoturismului"],
