      es: ["Superficie de aprox. 160 hectáreas.", "Situada en el río Esequibo cerca de Bartica.", "Alberga más de 180 especies de aves.", "La atracción principal es el perezoso de tres dedos.", "Solo accesible en bote.", "Eco-resort de gestión privada."],
      pt: ["Área de cerca de 160 hectares.", "Situada no Rio Essequibo, perto de Bartica.", "Abriga mais de 180 espécies de aves.", "A principal atração é a preguiça-de-três-dedos.", "Acessível apenas por barco.", "Eco-resort de gestão privada."],
      fr: ["Superficie d'environ 160 hectares.", "Située sur le fleuve Essequibo près de Bartica.", "Abrite plus de 180 espèces d'oiseaux.", "L'attraction principale est le paresseux à trois doigts.", "Accessible uniquement par bateau.", "Éco-resort privé."],
