      fr: ["Le mont Ayanganna mesure 2 041 m de haut.", "Il a été gravi pour la première fois en 1979.", "Il se situe dans la chaîne des Pacaraima.", "La montagne fait partie de la forêt d'Iwokrama.", "Les précipitations annuelles dépassent 3 000 mm.", "La température au sommet est de 15 °C en moyenne."],
